package com.edunexa.app
import android.content.Intent
import android.graphics.Color
import android.os.Bundle
import android.view.View
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import com.edunexa.app.data.*
import com.google.android.material.card.MaterialCardView
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
class AdminActivity:EduActivity(){private val repo=AdminRepository();private val coupons=CouponRepository();private val db=FirebaseFirestore.getInstance();private lateinit var list:LinearLayout;private lateinit var status:TextView;private lateinit var progress:ProgressBar;private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt();override fun onCreate(b:Bundle?){super.onCreate(b);setContentView(R.layout.activity_admin);list=findViewById(R.id.schoolList);status=findViewById(R.id.adminStatus);progress=findViewById(R.id.adminProgress);findViewById<Button>(R.id.pendingTab).setOnClickListener{loadSchools()};findViewById<Button>(R.id.usersTab).setOnClickListener{loadUsers()};findViewById<Button>(R.id.couponsTab).setOnClickListener{loadCoupons()};findViewById<Button>(R.id.proTab).setOnClickListener{loadPro()};findViewById<Button>(R.id.logoutBtn).setOnClickListener{FirebaseAuth.getInstance().signOut();startActivity(Intent(this,AuthActivity::class.java).apply{flags=Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK});finish()};verify()}
private fun verify(){val uid=FirebaseAuth.getInstance().currentUser?.uid?:return finish();db.collection("users").document(uid).get().addOnSuccessListener{if(it.getString("role")!="admin")finish() else loadSchools()}.addOnFailureListener{finish()}}
private fun loadSchools(){progress.visibility=View.VISIBLE;list.removeAllViews();repo.pendingSchools({s->progress.visibility=View.GONE;status.text="Pending Schools: ${s.size}";s.forEach{school->card("${school.schoolName.ifBlank{school.name}}\n${school.email}","Approve","Reject",{repo.setSchoolApproval(school.uid,true){_,m->Toast.makeText(this,m,Toast.LENGTH_SHORT).show();loadSchools()}},{repo.setSchoolApproval(school.uid,false){_,m->Toast.makeText(this,m,Toast.LENGTH_SHORT).show();loadSchools()}})}},{status.text=it;progress.visibility=View.GONE})}
private fun loadUsers(){list.removeAllViews();status.text="User Management";db.collection("users").get().addOnSuccessListener{s->status.text="Users: ${s.size()}";s.documents.forEach{d->card("${d.getString("name")?:d.getString("schoolName")?:"User"}\n${d.getString("email")?:""}\nRole: ${d.getString("role")?:"—"}",null,null,null,null)}}.addOnFailureListener{status.text=it.message}}
private fun loadCoupons(){list.removeAllViews();status.text="Coupon Management";val code=EditText(this).apply{hint="Coupon code"};val discount=EditText(this).apply{hint="Discount 1-100";inputType=2};list.addView(code);list.addView(discount);list.addView(Button(this).apply{text="Create Coupon";setOnClickListener{coupons.createCoupon(code.text.toString(),discount.text.toString().toIntOrNull()?:0){_,m->Toast.makeText(this@AdminActivity,m,Toast.LENGTH_SHORT).show();loadCoupons()}}});coupons.all({rows->rows.forEach{c->card("${c.code} • ${c.discountPercent}% • ${if(c.active)"Active" else "Disabled"}",if(c.active)"Disable" else "Activate",null,{coupons.setActive(c.code,!c.active){_,m->Toast.makeText(this,m,Toast.LENGTH_SHORT).show();loadCoupons()}},null)}},{Toast.makeText(this,it,Toast.LENGTH_SHORT).show()})}
private fun loadPro(){list.removeAllViews();status.text="Membership Administration";val uid=EditText(this).apply{hint="User UID"};val days=EditText(this).apply{hint="Grant days (1–365)";inputType=android.text.InputType.TYPE_CLASS_NUMBER};list.addView(uid);list.addView(days);list.addView(Button(this).apply{text="Grant Pro";setOnClickListener{Backend.call("grantPro",mapOf("uid" to uid.text.toString(),"days" to (days.text.toString().toIntOrNull()?:0)),{status.text=it["message"].toString()},{status.text=it})}});val price=EditText(this).apply{hint="Paid Pro price in rupees";inputType=android.text.InputType.TYPE_CLASS_NUMBER};val period=EditText(this).apply{hint="Membership days";inputType=android.text.InputType.TYPE_CLASS_NUMBER};list.addView(price);list.addView(period);list.addView(Button(this).apply{text="Save & Enable Paid Plan";setOnClickListener{val amount=price.text.toString().toIntOrNull();val duration=period.text.toString().toIntOrNull();if(amount==null||amount !in 1..100000||duration==null||duration !in 1..365){status.text="Enter valid price and days";return@setOnClickListener};db.collection("plans").document("pro").set(mapOf("enabled" to true,"pricePaise" to amount*100,"days" to duration)).addOnSuccessListener{status.text="Plan saved. Payment account must be configured before accepting payments."}.addOnFailureListener{status.text=it.message}}});list.addView(Button(this).apply{text="Disable Paid Plan";setOnClickListener{db.collection("plans").document("pro").set(mapOf("enabled" to false),com.google.firebase.firestore.SetOptions.merge()).addOnSuccessListener{status.text="Paid plan disabled"}}});db.collection("users").whereEqualTo("pro",true).get().addOnSuccessListener{s->card("Active Pro Accounts\n${s.documents.count{(it.getLong("proUntil")?:0)>System.currentTimeMillis()}} user(s)",null,null,null,null)}.addOnFailureListener{status.text=it.message}}
private fun card(text:String,a:String?,b:String?,goA:(()->Unit)?,goB:(()->Unit)?){val c=MaterialCardView(this).apply{radius=dp(18).toFloat();setCardBackgroundColor(Color.WHITE);setContentPadding(dp(16),dp(16),dp(16),dp(16))};val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};box.addView(TextView(this).apply{this.text=text;textSize=16f});if(a!=null){val row=LinearLayout(this);row.addView(Button(this).apply{this.text=a;setOnClickListener{goA?.invoke()}});if(b!=null)row.addView(Button(this).apply{this.text=b;setOnClickListener{goB?.invoke()}});box.addView(row)};c.addView(box);list.addView(c,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,0,0,dp(10))})}}
